sp_AtualizarSenha	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_AtualizarSenha`(\n\n    IN idUsuario INT,\n\n    IN Senha     VARCHAR(255)\n\n)\nBEGIN\n\n    UPDATE Usuario SET Senha = Senha\n\n    WHERE idUsuario = idUsuario;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
